package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE, 44 bytes
	TierEntry struct { // group @0 len=11
		TierLimit decimal.Decimal // PIC 9(6)V99 @0 len=8
		TierRate  decimal.Decimal // PIC 9V99 @8 len=3
	}
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsIdx int64 // PIC 9 len=1 = 0
var WsTier int64 // PIC 9 len=1 = 0
var WsComm decimal.Decimal // PIC 9(6)V99 len=8 = 0
var WsTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsSalesEd string // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string // PIC 9.99 len=4
var WsCommEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14

var SrId string
var SrSales decimal.Decimal

// 1-based tier table (index 1..4)
var TierLimit [5]decimal.Decimal
var TierRate [5]decimal.Decimal

var inputLines []string
var inputPos int

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone() {
	WsEofFlag = "Y"
}

func formatIntPattern(value decimal.Decimal, intPattern string, fracDigits int) string {
	// truncate toward zero to fracDigits
	t := value.Truncate(int32(fracDigits))
	neg := t.IsNegative()
	abs := t.Abs()
	scaled := abs.Shift(int32(fracDigits)).Truncate(0)
	s64 := scaled.IntPart()
	pow := int64(1)
	for i := 0; i < fracDigits; i++ {
		pow *= 10
	}
	intVal := s64 / pow
	fracVal := s64 % pow
	// count digit slots
	N := 0
	for _, c := range intPattern {
		if c == 'Z' || c == '9' {
			N++
		}
	}
	s := fmt.Sprintf("%d", intVal)
	if len(s) > N {
		s = s[len(s)-N:]
	} else if len(s) < N {
		s = strings.Repeat("0", N-len(s)) + s
	}
	// first non-zero
	firstNZ := N - 1
	for i := 0; i < N; i++ {
		if s[i] != '0' {
			firstNZ = i
			break
		}
	}
	var b strings.Builder
	digitIdx := 0
	for _, c := range intPattern {
		switch c {
		case ',':
			if firstNZ < digitIdx {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		case 'Z', '9':
			ch := s[digitIdx]
			if digitIdx < firstNZ {
				b.WriteByte(' ')
			} else {
				b.WriteByte(ch)
			}
			digitIdx++
		default:
			b.WriteByte(byte(c))
		}
	}
	intPart := b.String()
	fracStr := fmt.Sprintf("%0*d", fracDigits, fracVal)
	_ = neg
	return intPart + "." + fracStr
}

func formatSales(v decimal.Decimal) string {
	return formatIntPattern(v, "ZZZ,ZZ9", 2)
}
func formatComm(v decimal.Decimal) string {
	return formatIntPattern(v, "ZZZ,ZZ9", 2)
}
func formatTotal(v decimal.Decimal) string {
	return formatIntPattern(v, "ZZZ,ZZZ,ZZ9", 2)
}
func formatRate(v decimal.Decimal) string {
	return formatIntPattern(v, "9", 2)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseSalesField(f string) decimal.Decimal {
	// DISPLAY numeric 9(6)V99 digits only
	f = strings.TrimSpace(f)
	if f == "" {
		return decimal.Zero
	}
	// keep digits only
	digits := ""
	for _, c := range f {
		if c >= '0' && c <= '9' {
			digits += string(c)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	// strip leading zeros for conversion but keep at least one
	n := int64(0)
	for _, c := range digits {
		n = n*10 + int64(c-'0')
	}
	// digits represent value with 2 implied decimals; but leading zeros beyond 8? take low-order 8?
	// field width is 8 digits; if longer, keep low-order? input is exactly 8.
	// Build with Shift(-2)
	return decimal.New(n, -2)
}

func loadInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		inputLines = nil
		return
	}
	// split on \n, keep lines without newline; strip trailing \r
	s := strings.ReplaceAll(string(data), "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	parts := strings.Split(s, "\n")
	// If file ends with newline, last part is empty after final newline -> that is not a record.
	// COBOL LINE SEQUENTIAL: trailing newline does not create extra record.
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	inputLines = parts
	inputPos = 0
}

func INITPARA() {
	TierLimit[1] = decimal.NewFromFloat(1000.00)
	TierRate[1] = decimal.NewFromFloat(2.50)
	TierLimit[2] = decimal.NewFromFloat(5000.00)
	TierRate[2] = decimal.NewFromFloat(4.00)
	TierLimit[3] = decimal.NewFromFloat(20000.00)
	TierRate[3] = decimal.NewFromFloat(5.50)
	TierLimit[4] = decimal.NewFromFloat(999999.99)
	TierRate[4] = decimal.NewFromFloat(7.25)
	// Ensure exact scales
	TierLimit[1] = decimal.New(100000, -2)
	TierLimit[2] = decimal.New(500000, -2)
	TierLimit[3] = decimal.New(2000000, -2)
	TierLimit[4] = decimal.New(99999999, -2)
	TierRate[1] = decimal.New(250, -2)
	TierRate[2] = decimal.New(400, -2)
	TierRate[3] = decimal.New(550, -2)
	TierRate[4] = decimal.New(725, -2)
}

func READPARA() {
	if inputPos >= len(inputLines) {
		setInputDone()
		return
	}
	line := inputLines[inputPos]
	inputPos++
	// pad with spaces to 12 on right (bytes)
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	SrId = line[0:4]
	salesField := line[4:12]
	SrSales = parseSalesField(salesField)
}

func PROCESSPARA() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if SrSales.Cmp(TierLimit[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * RATE / 100
	prod := SrSales.Mul(TierRate[WsTier])
	q := prod.Shift(-2)
	r := q.Round(2)
	// store into 9(6)V99: truncate to 2 then keep low-order 8 digits
	r = r.Truncate(2)
	// overflow wrap: keep low-order digits
	sc := r.Shift(2).Truncate(0)
	// mod 10^8
	mod := int64(100000000)
	iv := sc.IntPart()
	// handle positive only; COBOL drops high-order digits (mod)
	// use decimal mod to avoid overflow issues for large (still fits int64)
	iv = iv % mod
	if iv < 0 {
		iv += mod
	}
	WsComm = decimal.New(iv, -2)
	WsTotal = WsTotal.Add(WsComm)
	// keep total within 9(9)V99? mod 10^11
	tmod := decimal.New(100000000000, 0) // 10^11
	// apply wrap via truncated scaled
	ts := WsTotal.Shift(2).Truncate(0)
	// decimal Mod
	ts = ts.Mod(tmod)
	// ts is 0..10^11-1, may be negative? totals positive
	WsTotal = ts.Shift(-2)
	WsCount = (WsCount + 1) % 1000
	WsSalesEd = formatSales(SrSales)
	WsRateEd = formatRate(TierRate[WsTier])
	WsCommEd = formatComm(WsComm)
	tierStr := fmt.Sprintf("%01d", WsTier)
	fmt.Println(SrId+" T"+tierStr+" "+WsSalesEd+" "+WsRateEd+"% "+WsCommEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatTotal(WsTotal)
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Println("REPS: "+countStr+" TOTAL: "+WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsIdx = 0
	WsTier = 0
	WsComm = decimal.Zero
	WsTotal = decimal.Zero
	WsCount = 0
	INITPARA()
	loadInput()
	// OPEN INPUT then READ
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	SUMMARYPARA()
	_ = bufio.NewReader
	_ = padRight
}
